# ===== Helpers =====
proc envOr*(name, fallback: string): string =
  let v = getEnv(name)
  if v.len > 0: v else: fallback

proc addCorsHeaders*(headers: var HttpHeaders) =
  headers["Access-Control-Allow-Origin"] = "*"
  headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS, PUT, DELETE"
  headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization, X-Requested-With"
  headers["Access-Control-Max-Age"] = "86400"

proc approxTokens*(s: string): int =
  # very rough heuristic ~ 4 chars/token
  max(1, s.len div 4)

# ===== External API Clients =====
proc cerebrasChat*(messages: JsonNode): Future[string] {.async.} =
  let client = newAsyncHttpClient()
  try:
    client.headers = newHttpHeaders({
      "Authorization": "Bearer " & envOr("CEREBRAS_API_KEY", CEREBRAS_API_KEY_DEFAULT),
      "Content-Type": "application/json"
    })
    let bodyJson = %*{
      "model": "gpt-oss-120b",
      "messages": messages,
      "stream": false,
      "max_completion_tokens": 65000,
      "temperature": 0.1,
      "top_p": 0.95
    }
    let response = await client.postContent("", $bodyJson)
    let jsonResponse = parseJson(response)
    if jsonResponse.hasKey("choices") and jsonResponse["choices"].len > 0:
      let choice = jsonResponse["choices"][0]
      if choice.hasKey("message") and choice["message"].hasKey("content"):
        result = choice["message"]["content"].getStr()
      else:
        result = ""
    else:
      result = ""
  finally:
    try: client.close() except: discard

proc exaSearch*(query: string; maxResults=100): Future[JsonNode] {.async.} =
  let client = newAsyncHttpClient()
  try:
    client.headers = newHttpHeaders({
      "Authorization": "Bearer " & envOr("EXA_API_KEY", EXA_API_KEY_DEFAULT),
      "Content-Type": "application/json"
    })
    let bodyJson = %*{
      "query": query,
      "type": "fast",
      "numResults": maxResults,
      "livecrawl": "never",
      "includeText": true,
      "textLength": 200000
    }
    let response = await client.postContent("", $bodyJson)
    result = parseJson(response)
  finally:
    try: client.close() except: discard

# ===== Research Pipeline =====
proc performDeepResearch*(userQuery: string): Future[JsonNode] {.async.} =
  var sources: seq[string] = @[]
  var researchData = newSeq

  let initial = await exaSearch(userQuery, 100)
  if initial.hasKey("results") and initial["results"].kind == JArray:
    for idx, item in initial["results"]:
      if idx.int >= 100: break
      let title = item.getOrDefault("title").getStr("Nincs cím")
      let url = item.getOrDefault("url").getStr("Nincs URL")
      let text = item.getOrDefault("text").getStr("")
      let score = item.getOrDefault("score").getFloat(0.0)
      if url.len > 0:
        sources.add(url)
      researchData.add(&"## Forrás {idx.int+1}: {title}\n**URL:** {url}\n**Relevancia:** {score:0.3f}\n**Tartalom:**\n{text}\n\n---\n")

  for q in [
    userQuery & " legfrissebb fejlemények",
    userQuery & " szakértői vélemények",
    userQuery & " statisztikák adatok",
    userQuery & " kutatási eredmények",
    userQuery & " nemzetközi perspektíva"
  ]:
    let add = await exaSearch(q, 100)
    if add.hasKey("results") and add["results"].kind == JArray:
      for _, item in add["results"]:
        let title = item.getOrDefault("title").getStr("Nincs cím")
        let url = item.getOrDefault("url").getStr("Nincs URL")
        let text = item.getOrDefault("text").getStr("")
        if url.len > 0 and (url notin sources):
          sources.add(url)
          researchData.add(&"### Kiegészítő forrás: {title}\n**URL:** {url}\n**Tartalom:**\n{text}\n\n---\n")

  let collected = researchData.join("\n")
  let analysisMessages = %*[
    {
      "role": "system",
      "content": &"Te egy világszínvonalú kutatási szakértő vagy. A felhasználó ezt kérdezte: \"{userQuery}\"\n\nFeladatod egy részletes, 15000 szavas kutatási jelentés készítése a következő struktúrával:\n\n# EXECUTIVE SUMMARY\n- Összefoglaló 3-5 mondatban\n\n# BEVEZETÉS\n- A téma jelentősége és relevanciája\n- Kutatási kérdések megfogalmazása\n- Módszertani megközelítés\n\n# FŐRÉSZ\n## 1. JELENLEGI HELYZET ELEMZÉSE\n- Státusz quo bemutatása\n- Kulcsfontosságú tényezők azonosítása\n- Számszerű adatok, statisztikák\n\n## 2. SZAKIRODALMI ÁTTEKINTÉS\n- Releváns kutatások összefoglalása\n- Szakértői vélemények\n- Ellentmondások és viták bemutatása\n\n## 3. NEMZETKÖZI PERSPEKTÍVA\n- Globális trendek\n- Országonkénti különbségek\n- Jövőbeli kilátások\n\n## 4. KOCKÁZATOK ÉS LEHETŐSÉGEK\n- Azonosított kockázatok\n- Potenciális előnyök\n- Stratégiai megfontolások\n\n## 5. ESETTANULMÁNYOK\n- Konkrét példák\n- Sikeres és sikertelen kezdeményezések\n- Tanulságok levonása\n\n# KÖVETKEZTETÉSEK ÉS JAVASLATOK\n- Kulcsfontosságú megállapítások\n- Praktikus ajánlások\n- Következő lépések\n\n# FORRÁSOK ÉS HIVATKOZÁSOK\n- Teljes forráslista\n- Megbízhatósági értékelés\n\nRENDKÍVÜL FONTOS:\n- Minden állítást konkrét forrásokkal támassz alá\n- Objektív, tudományos megközelítés\n- Magyar nyelv, szakszerű fogalmazás\n- Strukturált, logikus felépítés"
    },
    {
      "role": "user",
      "content": &"Készíts részletes kutatási jelentést erről a témáról: {userQuery}\n\nRendelkezésre álló kutatási anyagok:\n{collected}\n\nForráslistám ({$sources.len} db forrás):\n{sources.join(\"\\n\")}"
    }
  ]

  let report = await cerebrasChat(analysisMessages)
  let wc = report.splitWhitespace.len
  let tk = approxTokens(report)

  result = %*{
    "report": report,
    "wordCount": wc,
    "tokenEstimate": tk,
    "sourcesCount": sources.len,
    "sources": sources
  }

# ===== HTTP Server =====
var server = newAsyncHttpServer()

proc handleRequest(req: Request) {.async.} =
  var headers = newHttpHeaders()
  addCorsHeaders(headers)

  if req.reqMethod == HttpOptions:
    await req.respond(Http200, "", headers)
    return

  if req.url.path == "/" and req.reqMethod == HttpGet:
    try:
      let htmlContent = readFile("index.html")
      headers["Content-Type"] = "text/html; charset=utf-8"
      headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
      headers["Pragma"] = "no-cache"
      headers["Expires"] = "0"
      await req.respond(Http200, htmlContent, headers)
    except:
      await req.respond(Http404, "index.html nem található", headers)
    return

  if req.url.path == "/chat" and req.reqMethod == HttpPost:
    try:
      let body = req.body
      if body.len == 0:
        await req.respond(Http400, $(%*{"error": "Üres kérés"}), headers)
        return
      let payload = parseJson(body)
      let userMessage = payload.getOrDefault("message").getStr("")
      if userMessage.len == 0:
        await req.respond(Http400, $(%*{"error": "Üres üzenet"}), headers)
        return

      let messages = %*[
        {"role": "system", "content": "Magyar AI asszisztens vagy. Válaszolj informatívan, magyarul, teljes körűen."},
        {"role": "user", "content": userMessage}
      ]
      let content = await cerebrasChat(messages)
      headers["Content-Type"] = "application/json; charset=utf-8"
      await req.respond(Http200, $(%*{
        "response": content,
        "timestamp": $now(),
        "status": "success",
        "wordCount": content.splitWhitespace.len,
        "tokenEstimate": approxTokens(content)
      }), headers)
    except Exception as e:
      headers["Content-Type"] = "application/json; charset=utf-8"
      await req.respond(Http500, $(%*{"error": "Belső hiba", "details": e.msg}), headers)
    return

  if req.url.path == "/deepsearch" and req.reqMethod == HttpPost:
    try:
      let body = req.body
      if body.len == 0:
        await req.respond(Http400, $(%*{"error": "Üres kutatási kérés"}), headers)
        return
      let payload = parseJson(body)
      let query = payload.getOrDefault("query").getStr("")
      if query.len == 0:
        await req.respond(Http400, $(%*{"error": "Üres kutatási téma"}), headers)
        return

      let resultJson = await performDeepResearch(query)
      headers["Content-Type"] = "application/json; charset=utf-8"
      var reply = resultJson
      reply["query"] = %query
      reply["timestamp"] = %$now()
      reply["status"] = %"completed"
      await req.respond(Http200, $reply, headers)
    except Exception as e:
      headers["Content-Type"] = "application/json; charset=utf-8"
      await req.respond(Http500, $(%*{"error": "Kutatási hiba", "details": e.msg}), headers)
    return

  if req.url.path == "/status" and req.reqMethod == HttpGet:
    headers["Content-Type"] = "application/json; charset=utf-8"
    let statusInfo = %*{
      "status": "running",
      "timestamp": $now(),
      "endpoints": ["/", "/chat", "/deepsearch", "/status"],
      "environment": {
        "has_cerebras_key": envOr("CEREBRAS_API_KEY", CEREBRAS_API_KEY_DEFAULT).len > 0,
        "has_exa_key": envOr("EXA_API_KEY", EXA_API_KEY_DEFAULT).len > 0
      }
    }
    await req.respond(Http200, $statusInfo, headers)
    return

  headers["Content-Type"] = "application/json; charset=utf-8"
  await req.respond(Http404, $(%*{"error": "Endpoint nem található", "path": req.url.path, "method": $req.reqMethod}), headers)

proc startServer() {.async.} =
  let portStr = getEnv("PORT")
  let port = if portStr.len > 0: parseInt(portStr) else: 5000
  echo "🧠 JADED - AI Kutatási Asszisztens"
  echo "================================="
  echo &"🚀 Szerver indítás: 0.0.0.0:{port}"
  echo &"📡 Cerebras API kulcs: " & (if envOr("CEREBRAS_API_KEY", CEREBRAS_API_KEY_DEFAULT).len > 0: "✓" else: "✗")
  echo &"🔍 Exa API kulcs: " & (if envOr("EXA_API_KEY", EXA_API_KEY_DEFAULT).len > 0: "✓" else: "✗")
  echo "================================="
  await server.serve(Port(port), handleRequest, "0.0.0.0")

when isMainModule:
  waitFor startServer()
